            <div class="col-12"><div class="abs-card p-3 p-md-4"><div class="d-flex align-items-center justify-content-between gap-3 mb-3 abs-card-header"><div><h5 class="mb-1" style="color:#18324b">Find a flagged space</h5><small class="text-muted">Use one or more filters. Results are loaded in groups of 100.</small></div><button type="button" class="btn btn-light border btn-sm" id="absReset"><i class="fas fa-rotate-left me-1"></i>Reset</button></div><form id="absFilters"><div class="row g-3 align-items-end"><div class="col-12 col-md-6 col-lg-3"><label class="form-label" for="absSearch">Search</label><input class="form-control" id="absSearch" name="search" placeholder="Hall, block, room, bed or student ID" autocomplete="off"></div><div class="col-12 col-md-6 col-lg-2"><label class="form-label" for="absHall">Hall</label><select class="form-select" id="absHall" name="hall"><option value="all">All halls</option>@foreach($halls as $hall)<option value="{{ $hall }}">{{ $hall }}</option>@endforeach</select></div><div class="col-12 col-md-6 col-lg-2"><label class="form-label" for="absBlock">Block</label><select class="form-select" id="absBlock" name="block"><option value="all">All blocks</option>@foreach($blocks as $block)<option value="{{ $block }}">{{ $block }}</option>@endforeach</select></div><div class="col-6 col-md-3 col-lg-1"><label class="form-label" for="absRoom">Room</label><select class="form-select" id="absRoom" name="room"><option value="all">All</option>@foreach($rooms as $room)<option value="{{ $room }}">{{ $room }}</option>@endforeach</select></div><div class="col-6 col-md-3 col-lg-1"><label class="form-label" for="absBed">Bed</label><select class="form-select" id="absBed" name="bed"><option value="all">All</option>@foreach($beds as $bed)<option value="{{ $bed }}">{{ $bed }}</option>@endforeach</select></div><div class="col-12 col-md-6 col-lg-2"><label class="form-label" for="absOccupancy">Occupancy</label><select class="form-select" id="absOccupancy" name=