<div class="modal fade" id="absAssignModal" tabindex="-1" aria-labelledby="absAssignTitle" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content border-0 shadow"><div class="modal-header"><div><h5 class="modal-title" id="absAssignTitle">Assign this bed space</h5><div class="abs-modal-note" id="absAssignLocation"></div></div><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><form id="absAssignForm"><div class="modal-body"><label class="form-label" for="absAssignUsername">Student ID number</label><input class="form-control" id="absAssignUsername" name="username" required maxlength="100" autocomplete="off" placeholder="For example: 22/08/08/0010"><input type="hidden" id="absAssignId" name="id"><div class="abs-modal-note mt-2">The student must already have a record on the portal. The bed will be marked assigned after saving.</div><div class="abs-notice mt-3" id="absAssignNotice"></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button type="submit" class="btn btn-primary" id="absAssignSubmit"><i class="fas fa-user-plus me-1"></i>Assign space</button></div></form></div></div></div>

<script>
(() => {
    const root=document.querySelector('.abs-page'); if(!root)return;
    const csrf=@json(csrf_token()), endpoint=@json(url('abs/data')), assignEndpoint=@json(url('abs/assign')), unflagEndpoint=@json(url('abs/unflag'));
    const state={page:1,loading:false,meta:{current_page:1,last_page:1,per_page:100,total:0,from:0,to:0}};
    const $=id=>document.getElementById(id);
    const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
    const filters=()=>{const p=new URLSearchParams();['search','hall','block','room','bed','occupancy','payment'].forEach(n=>{const e=$('abs'+n.charAt(0).toUpperCase()+n.slice(1));if(e&&e.value&&e.value!=='all')p.set(n,e.value)});p.set('per_page','100');p.set('page',String(state.page));return p};
    function notice(message,type='success',target='absNotice'){const n=$(target);n.textContent=message;n.className='abs-notice show '+type;setTimeout(()=>n.classList.remove('show'),5000)}
    function stats(s){$('absStatTotal').textContent=Number(s.total||0).toLocaleString();$('absStatAvailable').textContent=Number(s.available||0).toLocaleString();$('absStatOccupied').textContent=Number(s.occupied||0).toLocaleString();$('absStatPaid').textContent=Number(s.paid||0).toLocaleString()}
    function pagination(meta){state.meta=meta;const nav=$('absPagination');nav.innerHTML='';const add=(label,page,disabled=false,active=false)=>{const li=document.createElement('li');li.className='page-item'+(disabled?' disabled':'')+(active?' active':'');const b=document.createElement('button');b.type='button';b.className='page-link';b.textContent=label;b.disabled=disabled;if(!disabled&&!active)b.onclick=()=>{state.page=page;load()};li.appendChild(b);nav.appendChild(li)};add('Previous',Math.max(1,meta.current_page-1),meta.current_page<=1);const start=Math.max(1,meta.current_page-2),end=Math.min(meta.last_page,meta.current_page+2);for(let p=start;p<=end;p++)add(String(p),p,false,p===meta.current_page);add('Next',Math.min(meta.last_page,meta.current_page+1),meta.current_page>=meta.last_page);$('absPaginationLabel').textContent=meta.total?'Showing '+meta.from+'–'+meta.to+' of '+meta.total+' spaces':'No flagged spaces match these filters'}
    function rows(data,meta){const body=$('absRows');if(!data.length){body.innerHTML='<tr><td colspan="11" class="text-center py-5 text-muted"><i class="fas fa-bed d-block mb-2" style="font-size:1.8rem"></i>No flagged spaces match these filters.</td></tr>';$('absSelectAll').checked=false;return}body.innerHTML=data.map((r,i)=>{const occ=Number(r.status)===1;const paid=Number(r.hostel_payment)===1;const label=esc([r.hall,r.block,r.room,r.bed].filter(Boolean).join(' · '));return '<tr data-id="'+r.id+'"><td><input class="abs-check abs-row-check" type="checkbox" value="'+r.id+'" aria-label="Select '+label+'"></td><td>'+(((meta.current_page-1)*meta.per_page)+i+1)+'</td><td><strong>#'+r.id+'</strong></td><td><strong>'+esc(r.hall)+'</strong></td><td>'+esc(r.block||'—')+'</td><td>'+esc(r.room||'—')+'</td><td>'+esc(r.bed||'—')+'</td><td class="abs-occupancy-cell"><span class="abs-pill '+(occ?'occupied':'available')+'"><i class="fas '+(occ?'fa-user-check':'fa-circle-check')+'"></i>'+(occ?'Assigned':'Available')+'</span></td><td class="abs-student-cell">'+(occ?'<span class="abs-student-name" title="'+esc(r.student_name||'')+'">'+esc(r.student_name||'Name not available')+'</span><small class="d-block text-muted abs-occupant-cell">'+esc(r.occupant||'')+'</small>':'<span class="text-muted abs-student-name">No student assigned</span><small class="d-block text-muted abs-occupant-cell">—</small>')+'</td><td><span class="abs-pill '+(paid?'paid':'unpaid')+'"><i class="fas '+(paid?'fa-check':'fa-clock')+'"></i>'+(paid?'Paid':'Not paid')+'</span></td><td class="abs-action-cell">'+(occ?'<button type="button" class="btn btn-sm btn-light border" disabled><i class="fas fa-check me-1"></i>Assigned</button>':'<button type="button" class="btn btn-sm btn-primary abs-assign" data-id="'+r.id+'" data-location="'+label+'"><i class="fas fa-user-plus me-1"></i>Assign</button>')+'</td></tr>'}).join('');$('absSelectAll').checked=false}
    async function load(){if(state.loading)return;state.loading=true;$('absApply').disabled=true;$('absApply').innerHTML='<i class="fas fa-spinner fa-spin me-1"></i>Loading';$('absRows').innerHTML='<tr><td colspan="11" class="text-center py-5 text-muted"><i class="fas fa-spinner fa-spin me-2"></i>Loading spaces…</td></tr>';try{const res=await fetch(endpoint+'?'+filters(),{headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});const p=await res.json();if(!res.ok)throw Error(p.message||'The flagged spaces could not be loaded.');stats(p.stats||{});rows(p.data||[],p.meta||state.meta);pagination(p.meta||state.meta)}catch(e){$('absRows').innerHTML='<tr><td colspan="11" class="text-center py-5 text-danger">'+esc(e.message)+'</td></tr>';notice(e.message,'error')}finally{state.loading=false;$('absApply').disabled=false;$('absApply').innerHTML='<i class="fas fa-search me-1"></i>Find'}}
    function selected(){return [...root.querySelectorAll('.abs-row-check:checked')].map(x=>Number(x.value)).filter(Boolean)}
    function updateStatsAfterUnflag(n){const v=x=>Math.max(0,Number($(x).textContent.replace(/,/g,''))-n);$('absStatTotal').textContent=v('absStatTotal').toLocaleString();}
    async function unflag(){const ids=selected();if(!ids.length){notice('Select at least one bed space first.','error');return}const b=$('absUnflagSelected'),old=b.innerHTML;b.disabled=true;b.innerHTML='<i class="fas fa-spinner fa-spin me-1"></i>Saving';try{const res=await fetch(unflagEndpoint,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json','X-Requested-With':'XMLHttpRequest','X-CSRF-TOKEN':csrf},body:JSON.stringify({ids})});const p=await res.json();if(!res.ok)throw Error(p.message||'The selected spaces could not be unflagged.');ids.forEach(id=>root.querySelector('tr[data-id="'+id+'"]')?.remove());updateStatsAfterUnflag(ids.length);state.meta.total=Math.max(0,state.meta.total-ids.length);state.meta.to=Math.max(0,state.meta.to-ids.length);$('absPaginationLabel').textContent=state.meta.total?'Showing '+state.meta.from+'–'+state.meta.to+' of '+state.meta.total+' spaces':'No flagged spaces match these filters';notice(p.message)}catch(e){notice(e.message,'error')}finally{b.disabled=false;b.innerHTML=old}}
    root.querySelector('#absFilters').addEventListener('submit',e=>{e.preventDefault();state.page=1;load()});$('absReset').onclick=()=>{['absSearch','absHall','absBlock','absRoom','absBed','absOccupancy','absPayment'].forEach(id=>{const e=$(id);if(e)e.value=e.tagName==='SELECT'?'all':''});state.page=1;load()};$('absUnflagSelected').onclick=unflag;$('absSelectAll').onchange=e=>root.querySelectorAll('.abs-row-check').forEach(x=>x.checked=e.target.checked);
    root.addEventListener('click',e=>{const b=e.target.closest('.abs-assign');if(!b)return;$('absAssignId').value=b.dataset.id;$('absAssignUsername').value='';$('absAssignLocation').textContent=b.dataset.location||'';$('absAssignNotice').className='abs-notice';$('absAssignNotice').textContent='';if(window.bootstrap)bootstrap.Modal.getOrCreateInstance($('absAssignModal')).show();else $('absAssignModal').style.display='block'});
    $('absAssignForm').addEventListener('submit',async e=>{e.preventDefault();const b=$('absAssignSubmit'),id=Number($('absAssignId').value),username=$('absAssignUsername').value.trim(),old=b.innerHTML;b.disabled=true;b.innerHTML='<i class="fas fa-spinner fa-spin me-1"></i>Assigning';try{const res=await fetch(assignEndpoint,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json','X-Requested-With':'XMLHttpRequest','X-CSRF-TOKEN':csrf},body:JSON.stringify({id,username})});const p=await res.json();if(!res.ok)throw Error(p.message||'The bed space could not be assigned.');const tr=root.querySelector('tr[data-id="'+id+'"]');if(tr){tr.querySelector('.abs-occupancy-cell').innerHTML='<span class="abs-pill occupied"><i class="fas fa-user-check"></i>Assigned</span>';tr.querySelector('.abs-student-cell').innerHTML='<span class="abs-student-name" title="'+esc(p.name)+'">'+esc(p.name||'Name not available')+'</span><small class="d-block text-muted abs-occupant-cell">'+esc(p.occupant)+'</small>';tr.querySelector('.abs-action-cell').innerHTML='<button type="button" class="btn btn-sm btn-light border" disabled><i class="fas fa-check me-1"></i>Assigned</button>'}stats({total:Number($('absStatTotal').textContent.replace(/,/g,'')),available:Math.max(0,Number($('absStatAvailable').textContent.replace(/,/g,''))-1),occupied:Number($('absStatOccupied').textContent.replace(/,/g,''))+1,paid:Number($('absStatPaid').textContent.replace(/,/g,''))});notice(p.message);if(window.bootstrap)window.bootstrap.Modal.getOrCreateInstance($('absAssignModal')).hide();else $('absAssignModal').style.display='none'}catch(err){notice(err.message,'error','absAssignNotice')}finally{b.disabled=false;b.innerHTML=old}});
    load();
})();
</script>
